//! 🧱️ Nonuniform grid, exact mesh buffers, tile permissions and durable child targets.
use super::{Grid3dSnapshot,Grid3dTile,Grid3dTileMedia,Grid3dMesh,Grid3dColor,Grid3dRule,Grid3dDirection,Grid3dPinnedCell,Grid3dCell};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction,NativeEncodingBound,FloatColumn,FloatRow,insert_ieee754,insert_key_ieee754}}};
use std::collections::{BTreeMap,BTreeSet};
fn number(n:usize)->Result<i64,String>{i64::try_from(n).map_err(|_|"grid3d ordinal overflow".into())}
fn columns(table:&str)->&'static[FloatColumn]{match table{"wfc_grid3d_cell_size"=>&[FloatColumn::Binary64(4)],"wfc_grid3d_tile"=>&[FloatColumn::Binary64(5)],"wfc_grid3d_position"=>&[FloatColumn::Binary64(3)],_=>&[]}}
fn identity(r:FloatRow<'_>,n:usize)->Result<(),String>{if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=n{return Err("grid3d entity identity or column count differs".into())}Ok(())}
fn word(r:FloatRow<'_>,i:usize)->Result<u32,String>{u32::try_from(r.integer(i)?).map_err(|_|"grid3d unsigned32 differs".into())}
fn flag(r:FloatRow<'_>,i:usize)->Result<bool,String>{match r.integer(i)?{0=>Ok(false),1=>Ok(true),_=>Err("grid3d boolean differs".into())}}
fn rows<'a>(d:&'a SqliteDatabase,t:&str,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>,String>{let mut result=Vec::new();let mut ids=BTreeSet::new();for(i,r)in d.table(t)?.rows.iter().enumerate(){if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}let r=FloatRow::new(r,columns(t))?;if !ids.insert(r.rowid){return Err("duplicate grid3d row identity".into())}result.push(r);}Ok(result)}
fn ordered<'a>(mut rows:Vec<FloatRow<'a>>,ordinal:usize)->Result<Vec<FloatRow<'a>>,String>{rows.sort_by_key(|r|r.integer(ordinal).unwrap_or(-1));for(i,r)in rows.iter().enumerate(){if r.integer(ordinal)?!=number(i)?{return Err("grid3d ordinals must be contiguous".into())}}Ok(rows)}
fn groups<'a>(d:&'a SqliteDatabase,t:&str,n:usize,owners:&BTreeSet<i64>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<FloatRow<'a>>>,String>{let mut map=BTreeMap::<i64,Vec<FloatRow<'a>>>::new();for r in rows(d,t,c)?{identity(r,n)?;let owner=r.integer(1)?;if !owners.contains(&owner){return Err("grid3d relationship has unknown owner".into())}map.entry(owner).or_default().push(r);}Ok(map)}
fn parse_direction(s:&str)->Result<Grid3dDirection,String>{match s{"LEFT"=>Ok(Grid3dDirection::Left),"RIGHT"=>Ok(Grid3dDirection::Right),"FRONT"=>Ok(Grid3dDirection::Front),"BACK"=>Ok(Grid3dDirection::Back),"BOTTOM"=>Ok(Grid3dDirection::Bottom),"TOP"=>Ok(Grid3dDirection::Top),_=>Err("grid3d direction differs".into())}}
impl ArtifactSqliteSnapshot for Grid3dSnapshot{
const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
 let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;let mut total=1usize;for n in [self.cell_sizes_x.len(),self.cell_sizes_y.len(),self.cell_sizes_z.len(),self.tiles.len(),self.rules.len(),self.pinned.len(),self.masked.len()]{total=total.checked_add(n).ok_or("grid3d entity count overflow")?;p.check_rows(total)?;}for t in &self.tiles{total=total.checked_add(match &t.media{Grid3dTileMedia::Mesh{mesh}=>1usize.checked_add(mesh.positions.len()).and_then(|n|n.checked_add(mesh.indices.len())).and_then(|n|n.checked_add(usize::from(mesh.color.is_some()))).ok_or("grid3d mesh entity count overflow")?,Grid3dTileMedia::MeshChild{..}=>1}).ok_or("grid3d entity count overflow")?;p.check_rows(total)?;p.checkpoint()?;}
 p.insert_key("wfc_grid3d_document",1,&[Cell::Text(&self.schema),Cell::Text(&self.seed.to_string()),Cell::Integer(i64::from(self.width)),Cell::Integer(i64::from(self.height)),Cell::Integer(i64::from(self.depth)),Cell::Integer(i64::from(self.periodic_x)),Cell::Integer(i64::from(self.periodic_y)),Cell::Integer(i64::from(self.periodic_z))])?;
 for(axis,sizes)in [("x",&self.cell_sizes_x),("y",&self.cell_sizes_y),("z",&self.cell_sizes_z)]{for(i,size)in sizes.iter().enumerate(){insert_ieee754(&mut p,"wfc_grid3d_cell_size",&[Cell::Integer(1),Cell::Text(axis),Cell::Integer(number(i)?),Cell::Real(*size)],columns("wfc_grid3d_cell_size"))?;}}
 let mut tiles=BTreeMap::new();for(i,t)in self.tiles.iter().enumerate(){let kind=match &t.media{Grid3dTileMedia::Mesh{..}=>"mesh",Grid3dTileMedia::MeshChild{..}=>"mesh_child"};let id=insert_ieee754(&mut p,"wfc_grid3d_tile",&[Cell::Integer(1),Cell::Integer(number(i)?),Cell::Text(&t.id),t.label.as_deref().map_or(Cell::Null,Cell::Text),Cell::Real(t.weight),Cell::Text(kind)],columns("wfc_grid3d_tile"))?;if tiles.insert(t.id.as_str(),id).is_some(){return Err("duplicate grid3d tile authored identity".into())}match &t.media{Grid3dTileMedia::Mesh{mesh}=>{p.insert_key("wfc_grid3d_mesh",id,&[])?;for(i,v)in mesh.positions.iter().enumerate(){insert_ieee754(&mut p,"wfc_grid3d_position",&[Cell::Integer(id),Cell::Integer(number(i)?),Cell::Real(*v)],columns("wfc_grid3d_position"))?;}for(i,v)in mesh.indices.iter().enumerate(){p.insert("wfc_grid3d_index",&[Cell::Integer(id),Cell::Integer(number(i)?),Cell::Integer(i64::from(*v))])?;}if let Some(color)=mesh.color{p.insert_key("wfc_grid3d_color",id,&[Cell::Integer(i64::from(color.r)),Cell::Integer(i64::from(color.g)),Cell::Integer(i64::from(color.b)),Cell::Integer(i64::from(color.a))])?;}},Grid3dTileMedia::MeshChild{child}=>{let r=&child.target;p.insert_key("wfc_grid3d_mesh_child",id,&[Cell::Text(&child.child_id),Cell::Text(&r.artifact_id),Cell::Text(&r.dialect.artifact_kind),Cell::Text(&r.dialect.standard),Cell::Text(&r.dialect.subset)])?;}}}
 let mut rules=BTreeSet::new();for(i,r)in self.rules.iter().enumerate(){if !rules.insert(&r.id){return Err("duplicate grid3d rule authored identity".into())}p.insert("wfc_grid3d_rule",&[Cell::Integer(1),Cell::Integer(number(i)?),Cell::Text(&r.id),Cell::Integer(*tiles.get(r.tile_a_id.as_str()).ok_or("dangling grid3d rule tile A")?),Cell::Integer(*tiles.get(r.tile_b_id.as_str()).ok_or("dangling grid3d rule tile B")?),Cell::Text(r.direction.label()),Cell::Integer(i64::from(r.allowed))])?;}
 for(i,r)in self.pinned.iter().enumerate(){p.insert("wfc_grid3d_pin",&[Cell::Integer(1),Cell::Integer(number(i)?),Cell::Integer(i64::from(r.x)),Cell::Integer(i64::from(r.y)),Cell::Integer(i64::from(r.z)),Cell::Integer(*tiles.get(r.tile_id.as_str()).ok_or("dangling grid3d pinned tile")?)])?;}
 for(i,r)in self.masked.iter().enumerate(){p.insert("wfc_grid3d_mask",&[Cell::Integer(1),Cell::Integer(number(i)?),Cell::Integer(i64::from(r.x)),Cell::Integer(i64::from(r.y)),Cell::Integer(i64::from(r.z))])?;}
 p.finish()
}
fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
 validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits()).map_err(|e|e.to_string())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let doc=FloatRow::new(d.table("wfc_grid3d_document")?.single_row()?,&[])?;identity(doc,9)?;if doc.rowid!=1{return Err("grid3d root identity must be one".into())}let seed=doc.text(2)?.parse::<u64>().map_err(|_|"grid3d seed exceeds unsigned64")?;if seed.to_string()!=doc.text(2)?{return Err("grid3d seed requires canonical decimal".into())}
 let root=BTreeSet::from([1]);let tile_rows=ordered(groups(d,"wfc_grid3d_tile",7,&root,c)?.remove(&1).unwrap_or_default(),2)?;let mut names=BTreeMap::new();let mut authored=BTreeSet::new();let mut mesh_ids=BTreeSet::new();let mut child_ids=BTreeSet::new();for r in &tile_rows{if !authored.insert(r.text(3)?){return Err("duplicate grid3d authored tile identity".into())}names.insert(r.rowid,r.text(3)?);match r.text(6)?{"mesh"=>{mesh_ids.insert(r.rowid);},"mesh_child"=>{child_ids.insert(r.rowid);},_=>return Err("grid3d tile media kind differs".into())}}
 let meshes=rows(d,"wfc_grid3d_mesh",c)?;let mut seen=BTreeSet::new();for r in meshes{identity(r,1)?;if !mesh_ids.contains(&r.rowid){return Err("grid3d mesh has wrong tile kind or owner".into())}seen.insert(r.rowid);}if seen!=mesh_ids{return Err("grid3d mesh ownership is incomplete".into())}
 let mut positions=groups(d,"wfc_grid3d_position",4,&mesh_ids,c)?;let mut indices=groups(d,"wfc_grid3d_index",4,&mesh_ids,c)?;let mut colors=BTreeMap::new();for r in rows(d,"wfc_grid3d_color",c)?{identity(r,5)?;if !mesh_ids.contains(&r.rowid){return Err("grid3d color has unknown mesh".into())}colors.insert(r.rowid,r);}
 let mut children=BTreeMap::new();for r in rows(d,"wfc_grid3d_mesh_child",c)?{identity(r,6)?;if !child_ids.contains(&r.rowid){return Err("grid3d child has wrong tile kind or owner".into())}children.insert(r.rowid,r);}if children.len()!=child_ids.len(){return Err("grid3d child ownership is incomplete".into())}
 let mut axes=BTreeMap::<String,Vec<FloatRow<'_>>>::new();for r in rows(d,"wfc_grid3d_cell_size",c)?{identity(r,5)?;if r.integer(1)?!=1||!matches!(r.text(2)?,"x"|"y"|"z"){return Err("grid3d cell size owner or axis differs".into())}axes.entry(r.text(2)?.into()).or_default().push(r);}
 let rule_rows=ordered(groups(d,"wfc_grid3d_rule",8,&root,c)?.remove(&1).unwrap_or_default(),2)?;let pin_rows=ordered(groups(d,"wfc_grid3d_pin",7,&root,c)?.remove(&1).unwrap_or_default(),2)?;let mask_rows=ordered(groups(d,"wfc_grid3d_mask",6,&root,c)?.remove(&1).unwrap_or_default(),2)?;
 let mut owned=Reconstruction::new(c)?;let schema=owned.text(doc.text(1)?)?;let mut cell_sizes=[Vec::new(),Vec::new(),Vec::new()];for(i,axis)in ["x","y","z"].iter().enumerate(){for r in ordered(axes.remove(*axis).unwrap_or_default(),3)?{owned.scalar()?;cell_sizes[i].push(r.real(4)?);}}
 let mut tiles=Vec::new();for r in tile_rows{owned.scalar()?;let media=match r.text(6)?{"mesh"=>{let mut native_positions=Vec::new();for v in ordered(positions.remove(&r.rowid).unwrap_or_default(),2)?{owned.scalar()?;native_positions.push(v.real(3)?);}let mut native_indices=Vec::new();for v in ordered(indices.remove(&r.rowid).unwrap_or_default(),2)?{owned.scalar()?;native_indices.push(word(v,3)?);}let color=match colors.remove(&r.rowid){None=>None,Some(v)=>{for _ in 0..4{owned.scalar()?;}Some(Grid3dColor{r:word(v,1)?,g:word(v,2)?,b:word(v,3)?,a:word(v,4)?})}};Grid3dTileMedia::Mesh{mesh:Grid3dMesh{positions:native_positions,indices:native_indices,color}}},"mesh_child"=>{let v=children.remove(&r.rowid).ok_or("grid3d child absent")?;let target=store::os_io::ArtifactRef{artifact_id:owned.text(v.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:owned.text(v.text(3)?)?,standard:owned.text(v.text(4)?)?,subset:owned.text(v.text(5)?)?}};Grid3dTileMedia::MeshChild{child:store::ArtifactChild::new(owned.text(v.text(1)?)?,target)}},_=>unreachable!()};tiles.push(Grid3dTile{id:owned.text(r.text(3)?)?,label:r.optional_text(4)?.map(|s|owned.text(s)).transpose()?,weight:r.real(5)?,media});}
 let mut rules=Vec::new();let mut rule_ids=BTreeSet::new();for r in rule_rows{if !rule_ids.insert(r.text(3)?){return Err("duplicate grid3d rule authored identity".into())}owned.scalar()?;rules.push(Grid3dRule{id:owned.text(r.text(3)?)?,tile_a_id:owned.text(names.get(&r.integer(4)?).copied().ok_or("dangling grid3d rule tile A")?)?,tile_b_id:owned.text(names.get(&r.integer(5)?).copied().ok_or("dangling grid3d rule tile B")?)?,direction:parse_direction(r.text(6)?)?,allowed:flag(r,7)?});}
 let mut pinned=Vec::new();for r in pin_rows{for _ in 0..3{owned.scalar()?;}pinned.push(Grid3dPinnedCell{x:word(r,3)?,y:word(r,4)?,z:word(r,5)?,tile_id:owned.text(names.get(&r.integer(6)?).copied().ok_or("dangling grid3d pinned tile")?)?});}
 let mut masked=Vec::new();for r in mask_rows{for _ in 0..3{owned.scalar()?;}masked.push(Grid3dCell{x:word(r,3)?,y:word(r,4)?,z:word(r,5)?});}for _ in 0..7{owned.scalar()?;}owned.checkpoint()?;let [cell_sizes_x,cell_sizes_y,cell_sizes_z]=cell_sizes;
 Ok(Self{schema,seed,width:word(doc,3)?,height:word(doc,4)?,depth:word(doc,5)?,periodic_x:flag(doc,6)?,periodic_y:flag(doc,7)?,periodic_z:flag(doc,8)?,cell_sizes_x,cell_sizes_y,cell_sizes_z,tiles,rules,pinned,masked})
}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=NativeEncodingBound::new(c)?;b.add(4096)?;b.repeated(self.schema.len(),16)?;let mut total=1usize;for n in [self.tiles.len(),self.rules.len(),self.pinned.len(),self.masked.len(),self.cell_sizes_x.len(),self.cell_sizes_y.len(),self.cell_sizes_z.len()]{total=total.checked_add(n).ok_or("grid3d native entity overflow")?;b.check_rows(total)?;}for sizes in [&self.cell_sizes_x,&self.cell_sizes_y,&self.cell_sizes_z]{for _ in sizes{b.add(2048)?;}}
 for t in &self.tiles{b.repeated(t.id.len(),16)?;if let Some(label)=&t.label{b.repeated(label.len(),16)?;}b.add(4096)?;match &t.media{Grid3dTileMedia::Mesh{mesh}=>{total=total.checked_add(mesh.positions.len()).and_then(|n|n.checked_add(mesh.indices.len())).ok_or("grid3d native mesh count overflow")?;b.check_rows(total)?;for _ in &mesh.positions{b.add(2048)?;}for _ in &mesh.indices{b.add(256)?;}if mesh.color.is_some(){b.add(1024)?;}},Grid3dTileMedia::MeshChild{child}=>{let r=&child.target;for s in [&child.child_id,&r.artifact_id,&r.dialect.artifact_kind,&r.dialect.standard,&r.dialect.subset]{b.repeated(s.len(),16)?;}}}}
 for r in &self.rules{for s in [&r.id,&r.tile_a_id,&r.tile_b_id]{b.repeated(s.len(),16)?;}b.add(1024)?;}for r in &self.pinned{b.repeated(r.tile_id.len(),16)?;b.add(1024)?;}b.repeated(self.masked.len(),1024)?;b.finish()}
fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;if dialect.artifact_kind!="s.wfc.grid3d"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("grid3d dialect differs from its owned wildcard").into())}if d.table("wfc_grid3d_document")?.single_row()?.text(1)?!=self.schema{return Err(String::from("grid3d projected schema differs").into())}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}
}
